<template>
  <div class="fs-page data-vault">
    <header class="fs-page__header"><div><h1 class="fs-page__title">数据资产</h1><p class="fs-page__subtitle">原始交易、政策依据和加密结果，各有出处。</p></div><div class="fs-toolbar__right"><el-button @click="downloadTemplate">CSV 模板</el-button><el-button type="primary" @click="fileInput?.click()" :loading="importing">导入交易</el-button><input ref="fileInput" type="file" accept=".csv,text/csv" hidden @change="importFile"/></div></header>
    <div v-if="tab!=='finance'" class="fs-toolbar"><el-button @click="showProvenance">数据来源与分级依据</el-button></div>
    <el-dialog v-model="provenanceOpen" title="数据来源与分级依据" width="min(920px,94vw)" append-to-body>
      <template v-if="provenance">
        <p>{{ provenance.source }}</p>
        <template v-if="provenance.dataset"><dl class="wb-dl"><div><dt>原始明细</dt><dd>{{provenance.dataset.rawRows.toLocaleString()}} 条</dd></div><div><dt>汇总订单</dt><dd>{{provenance.dataset.orders.toLocaleString()}} 份</dd></div><div><dt>默认正向订单</dt><dd>{{provenance.dataset.eligibleOrders.toLocaleString()}} 份</dd></div><div><dt>客户国家</dt><dd>{{provenance.dataset.countries}} 个</dd></div></dl><p>{{provenance.dataset.transformation}}</p><p>{{provenance.dataset.limitations}}</p><p><a :href="provenance.dataset.sourceUrl" target="_blank" rel="noopener noreferrer">UCI 官方数据来源</a> · {{provenance.dataset.license}} · {{provenance.dataset.period}}</p><details><summary>原始文件校验值</summary><code style="overflow-wrap:anywhere">{{provenance.dataset.workbookSha256}}</code><p>{{provenance.dataset.attribution}}</p></details></template>
        <dl class="wb-dl"><div><dt>{{provenance.dataset?'默认模拟交易':'内置交易'}}</dt><dd>{{ provenance.seeded }} 笔</dd></div><div><dt>当前账号导入</dt><dd>{{ provenance.imported }} 笔</dd></div><div><dt>商户标识</dt><dd>{{ provenance.merchants }} 个</dd></div><div><dt>币种</dt><dd>{{ provenance.currencies.join(' / ') }}</dd></div></dl>
        <p class="fs-muted">{{ provenance.generator }}</p>
        <el-table :data="provenance.fields"><el-table-column prop="name" label="字段"/><el-table-column prop="key" label="字段键"/><el-table-column prop="level" label="级别" width="80"/><el-table-column prop="basis" label="依据" min-width="220"/></el-table>
        <h3>初筛模型的数据</h3><p>{{ provenance.modelSource }}</p><p v-if="provenance.model.kind==='anomaly'">真实订单拟合 {{provenance.model.trainingRows}} 份，时间留出 {{provenance.model.validationRows}} 份；留出告警率 {{(provenance.model.validationAlertRate*100).toFixed(2)}}%。无欺诈标签，不报告AUC。</p><p v-else>留出 AUC {{ provenance.model.validationAuc }}；不代表真实业务欺诈识别准确率。</p>
        <template v-if="provenance.imports.length"><h3>当前账号导入记录</h3><el-table :data="provenance.imports"><el-table-column prop="filename" label="文件"/><el-table-column prop="count" label="笔数" width="80"/><el-table-column prop="createdAt" label="导入时间"/></el-table><p class="fs-muted">导入记录只能证明文件来源，不代表系统已核验其真实性或使用授权。</p></template>
      </template>
    </el-dialog>
    <el-tabs v-model="tab" @tab-change="changeTab">
      <el-tab-pane label="金融数据库" name="finance"/><el-tab-pane label="电商订单与导入" name="sources"/><el-tab-pane label="政策法规库" name="policies"/><el-tab-pane label="加密样本库" name="protected"/>
    </el-tabs>
    <div v-if="tab!=='finance'" class="fs-toolbar"><el-select v-if="sourceMode==='public' && tab==='sources'" v-model="sourceScope" style="width:180px" @change="search"><el-option label="真实公开交易" value="public"/><el-option label="自行导入记录" value="imports"/></el-select><el-input v-model="query" clearable placeholder="搜索编号、名称或内容" @keyup.enter="search" style="width:280px"/><el-select v-if="tab !== 'protected'" v-model="region" placeholder="全部地区" clearable @change="search" style="width:160px"><el-option v-for="r in regions" :key="r.value" :value="r.value" :label="r.label"/></el-select><el-select v-if="tab === 'policies'" v-model="verified" placeholder="校对状态" clearable style="width:150px"><el-option label="已人工校对" value="verified"/><el-option label="地区模板" value="template"/></el-select><el-button @click="search">查询</el-button><span class="fs-muted fs-toolbar__right">{{ total }} {{ tab==='sources' ? '笔交易' : '条记录' }}</span></div>
    <div v-if="loadError" class="wb-error" role="alert">读取失败。<el-button text @click="load">重试</el-button></div>
    <FinancialDataCenter v-if="tab==='finance'"/><template v-else-if="tab === 'sources'">
      <el-table :data="rows" v-loading="loading" @row-click="inspectSource" row-class-name="wb-click-row"><el-table-column prop="code" label="交易编号" min-width="170"/><el-table-column prop="merchantCode" label="商户标识" min-width="125"/><el-table-column label="金额" min-width="145" align="right"><template #default="{row}">{{ money(row.amount) }} {{ row.currency }}</template></el-table-column><el-table-column label="交易地区" min-width="125"><template #default="{row}">{{ row.region }} → {{ row.destRegion }}</template></el-table-column><el-table-column prop="occurredAt" label="交易时间" min-width="165"/><el-table-column prop="origin" label="数据来源" min-width="180"/><el-table-column width="65"><template #default><el-icon><ArrowRight /></el-icon></template></el-table-column></el-table>
      <el-pagination layout="total, prev, pager, next" :total="sourceTotal" :page-size="20" v-model:current-page="page" @current-change="loadSources"/>
    </template>
    <template v-else-if="tab === 'policies'">
      <p class="wb-source-note">{{ coverage.verifiedCount }} 条已校对 · {{ coverage.templateCount }} 条地区模板。模板用于提示，不作为自动放行或阻断的法律依据。</p>
      <el-table :data="filteredPolicies" v-loading="loading" @row-click="r=>policyDetail=r" row-class-name="wb-click-row"><el-table-column prop="code" label="法规编号" width="180"/><el-table-column prop="name" label="法规名称" min-width="280"/><el-table-column prop="regionName" label="司法辖区" width="140"/><el-table-column label="整理状态" width="140"><template #default="{row}"><span :class="['wb-verdict',row.verified?'approve':'manual']">{{ row.verified ? '已人工校对' : row.template ? '地区模板' : '参考框架' }}</span></template></el-table-column><el-table-column prop="updatedAt" label="库内整理日期" width="140"/><el-table-column width="65"><template #default><el-icon><ArrowRight /></el-icon></template></el-table-column></el-table>
    </template>
    <template v-else>
      <el-table :data="filteredProtected" v-loading="loading" @row-click="r=>cipherDetail=r" row-class-name="wb-click-row"><el-table-column prop="code" label="原始交易编号" min-width="180"/><el-table-column label="保护分级" min-width="160"><template #default="{row}"><span v-for="g in row.groups" :key="g.level" :class="['wb-level',g.level.toLowerCase()]">{{ g.level }}</span></template></el-table-column><el-table-column prop="runId" label="处理流程" min-width="220"/><el-table-column prop="createdAt" label="入库时间" min-width="175"/><el-table-column label="完整性摘要" min-width="190"><template #default="{row}"><code>{{ row.groups[0]?.digest.slice(0,16) }}…</code></template></el-table-column></el-table>
      <div v-if="!loading && !protectedRows.length" class="wb-empty">尚无加密样本。<el-button text @click="router.push('/workbench')">运行交易流程</el-button></div>
    </template>
    <el-drawer :model-value="Boolean(sourceDetail)" @close="sourceDetail=null" title="原始交易" size="min(960px,95vw)"><template v-if="sourceDetail"><p class="wb-source-note">{{ sourceDetail.origin }} · 原始数据只在当前授权页面展示。</p><dl class="wb-dl wb-dl--vertical"><div v-for="(v,k) in sourceDetail" :key="k"><dt>{{ fieldNames[k] || k }}</dt><dd>{{ v }}</dd></div></dl><template v-if="rawRecord"><h3>原始工作簿记录</h3><el-table :data="rawRecord.items"><el-table-column prop="source_row" label="原始行号" width="95"/><el-table-column prop="stock_code" label="商品编号" width="110"/><el-table-column prop="description" label="原始商品描述" min-width="210"/><el-table-column prop="quantity" label="数量" width="80"/><el-table-column prop="unit_price" label="单价 GBP" width="100"/></el-table><el-pagination layout="prev,pager,next,total" :total="rawRecord.total" :page-size="30" v-model:current-page="rawPage" @current-change="loadRaw"/></template><el-button @click="router.push('/workbench')">进入业务工作台</el-button></template></el-drawer>
    <el-drawer :model-value="Boolean(policyDetail)" @close="policyDetail=null" title="法规依据" size="min(580px,95vw)"><template v-if="policyDetail"><h2>{{ policyDetail.name }}</h2><p>{{ policyDetail.regionName }} · {{ policyDetail.code }}</p><dl class="wb-dl wb-dl--vertical"><div v-for="key in ['sensitiveScope','transferRule','subjectRights','authority']" :key="key"><dt>{{ policyLabels[key] }}</dt><dd>{{ policyDetail[key] }}</dd></div></dl><p class="wb-source-note">此处为项目资料中的整理摘要，不是实时法律结论。实际门禁及其输入凭证在业务工作台展示。</p><el-button @click="router.push('/workbench')">查看合规流程</el-button></template></el-drawer>
    <el-drawer :model-value="Boolean(cipherDetail)" @close="cipherDetail=null" title="分级密文信封" size="min(640px,95vw)"><template v-if="cipherDetail"><h3 class="fs-mono">{{ cipherDetail.code }}</h3><div v-for="g in cipherDetail.groups" :key="g.level" class="wb-envelope"><div class="wb-section-head"><span :class="['wb-level',g.level.toLowerCase()]">{{ g.level }}</span><strong>{{ g.cipher }}</strong></div><span class="fs-muted">SHA-256 摘要</span><code>{{ g.digest }}</code><span class="fs-muted">密文</span><pre>{{ g.ciphertext }}</pre></div><el-button @click="router.push('/workbench?run='+cipherDetail.runId)">查看来源流程</el-button></template></el-drawer>
  </div>
</template>
<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { metaApi, workbenchApi } from '@/api'
import FinancialDataCenter from '@/components/FinancialDataCenter.vue'
const route=useRoute(),router=useRouter(),tab=ref(['finance','sources','policies','protected'].includes(route.query.tab)?route.query.tab:'finance')
const query=ref(''),region=ref(''),verified=ref(''),page=ref(1),rows=ref([]),sourceTotal=ref(0),policies=ref([]),protectedRows=ref([]),regions=ref([]),coverage=ref({}),loading=ref(false),loadError=ref(false),importing=ref(false),fileInput=ref(null)
const sourceDetail=ref(null),policyDetail=ref(null),cipherDetail=ref(null),rawRecord=ref(null),rawPage=ref(1),sourceMode=ref(''),sourceScope=ref('public')
const provenanceOpen=ref(false),provenance=ref(null)
async function showProvenance(){try{provenance.value=await workbenchApi.provenance();provenanceOpen.value=true}catch{ElMessage.error('无法读取数据来源')}}
const fieldNames={datasetId:'数据集',invoiceNo:'原始发票号',customerId:'原始匿名客户编号',customerCountry:'客户国家',lineCount:'明细数',quantity:'商品件数',sourceNote:'来源说明',code:'交易编号',merchantCode:'商户标识',amount:'金额',currency:'币种',region:'来源地区',destRegion:'目的地区',occurredAt:'交易时间',origin:'数据来源',account:'结算账户',counterparties:'交易对手数',category:'商品类别',key:'数据索引'}
const policyLabels={sensitiveScope:'敏感范围',transferRule:'库内传输要求摘要',subjectRights:'主体权利',authority:'主管机构'}
const match=r=>!query.value || JSON.stringify(r).toLowerCase().includes(query.value.toLowerCase())
watch(()=>route.query.tab,value=>{const next=['finance','sources','policies','protected'].includes(value)?value:'finance';if(next!==tab.value){tab.value=next;query.value='';region.value='';verified.value='';page.value=1;load()}})
const filteredPolicies=computed(()=>policies.value.filter(r=>match(r)&&(!region.value||r.region===region.value)&&(!verified.value||(verified.value==='verified'?r.verified:r.template))))
const filteredProtected=computed(()=>protectedRows.value.filter(match))
const total=computed(()=>tab.value==='sources'?sourceTotal.value:tab.value==='policies'?filteredPolicies.value.length:filteredProtected.value.length)
const money=v=>Number(v).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})
async function inspectSource(r){sourceDetail.value=r;rawRecord.value=null;rawPage.value=1;await loadRaw()}
async function loadRaw(){const code=sourceDetail.value?.code;if(sourceDetail.value?.datasetId!=='uci-online-retail-352')return;try{const result=await workbenchApi.publicRecord(code,rawPage.value);if(sourceDetail.value?.code===code)rawRecord.value=result}catch{}}
async function loadSources(){const d=await workbenchApi.sources({page:page.value,size:20,q:query.value,region:region.value,scope:sourceScope.value});rows.value=d.items;sourceTotal.value=d.total}
async function load(){if(tab.value==='finance'){loadError.value=false;return}loading.value=true;loadError.value=false;try{if(tab.value==='sources')await loadSources();else if(tab.value==='policies'){const d=await metaApi.regulations();policies.value=Array.isArray(d)?d:d.items || d.regulations || []}else protectedRows.value=await workbenchApi.protected()}catch{loadError.value=true}finally{loading.value=false}}
function search(){page.value=1;load()}
function changeTab(){query.value='';region.value='';verified.value='';router.replace({path:'/data',query:{tab:tab.value}});load()}
function downloadTemplate(){const text='code,merchantCode,amount,currency,region,destRegion,counterparties,category,occurredAt\nDEMO-001,DEMO-M01,1250.00,CNY,CN,EU,2,电子产品,2026-11-05 10:00:00\nDEMO-002,DEMO-M02,2300.00,CNY,CN,EU,3,家居用品,2026-11-05 11:00:00\n';const url=URL.createObjectURL(new Blob(['\ufeff'+text],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='FedShield交易导入模板.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function importFile(event){const f=event.target.files?.[0];if(!f)return;importing.value=true;try{const d=await workbenchApi.importCsv(f);ElMessage.success(`已导入 ${d.count} 笔交易`);tab.value='sources';sourceScope.value='imports';query.value=f.name;page.value=1;await load()}catch{}finally{event.target.value='';importing.value=false}}
onMounted(async()=>{try{const o=await workbenchApi.overview();regions.value=o.regions;coverage.value=o.policy;sourceMode.value=o.sourceMode}catch{loadError.value=true}await load()})
</script>
